SELECT 
FROM analysis_jobs
WHERE case_id = #{caseId}
  AND search_condition_id = #{searchConditionId}
  AND recording_id = #{recordingId}
  AND job_type = 'RECORDING_ANALYSIS'
  AND status IN ('QUEUED', 'RUNNING')
ORDER BY id DESC
LIMIT 1

SELECT 
FROM analysis_jobs
WHERE case_id = #{caseId}
  AND id = #{jobId}
  AND job_type = 'RECORDING_ANALYSIS'

SELECT FROM analysis_jobs WHERE job_type = 'RECORDING_ANALYSIS' AND case_id IN
#{caseId}
ORDER BY requested_at DESC, id DESC

mapper.update:
UPDATE analysis_jobs
SET claim_expires_at = #{leaseExpiresAt,typeHandler=com.ssafy.eyesonu.common.persistence.mybatis.UtcInstantTypeHandler}
WHERE id = #{jobId}
  AND job_type = 'RECORDING_ANALYSIS'
  AND status = 'RUNNING'
  AND claimed_by = #{workerId}
  AND lease_token_hash = #{leaseTokenHash}
  AND claim_expires_at > UTC_TIMESTAMP(6)

UPDATE analysis_jobs
SET status = 'FAILED', completed_at = UTC_TIMESTAMP(6), error_message = #{errorMessage}
WHERE case_id = #{caseId} AND id = #{jobId}
  AND job_type = 'RECORDING_ANALYSIS' AND status = 'RUNNING'
